import{_ as t}from"./chunks/sh1.DiUu_JVG.js";import{_ as a,c as o,o as n,ae as i}from"./chunks/framework.BrQRMotl.js";const _=JSON.parse('{"title":"Extended Note Block Basics","description":"","frontmatter":{},"headers":[],"relativePath":"manual/extended_note_block.md","filePath":"manual/extended_note_block.md"}'),l={name:"manual/extended_note_block.md"};function s(r,e,d,c,h,u){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="extended-note-block-basics" tabindex="-1">Extended Note Block Basics <a class="header-anchor" href="#extended-note-block-basics" aria-label="Permalink to &quot;Extended Note Block Basics&quot;">​</a></h1><p>The <strong>Extended Note Block</strong> is the core of this mod. Compared to the vanilla Note Block, it offers more precise control and richer features.</p><h2 id="placement-and-basic-settings" tabindex="-1">Placement and Basic Settings <a class="header-anchor" href="#placement-and-basic-settings" aria-label="Permalink to &quot;Placement and Basic Settings&quot;">​</a></h2><ul><li><strong>Placement</strong>: Place the <strong>Extended Note Block</strong> just like a vanilla Note Block.</li><li><strong>Open Interface</strong>: <strong>Right Click</strong> the block to open its configuration interface.</li></ul><p><img src="'+t+'" alt="Extended Note Block GUI"></p><h2 id="parameter-details" tabindex="-1">Parameter Details <a class="header-anchor" href="#parameter-details" aria-label="Permalink to &quot;Parameter Details&quot;">​</a></h2><p>In the basic settings interface, you can configure the following parameters:</p><h3 id="_1-note-pitch" tabindex="-1">1. Note (Pitch) <a class="header-anchor" href="#_1-note-pitch" aria-label="Permalink to &quot;1. Note (Pitch)&quot;">​</a></h3><ul><li><strong>Range</strong>: 0 - 127 (corresponding to the MIDI standard).</li><li>Unlike the vanilla 0-24 limit, here you can play sounds spanning 10 octaves.</li></ul><h3 id="_2-velocity" tabindex="-1">2. Velocity <a class="header-anchor" href="#_2-velocity" aria-label="Permalink to &quot;2. Velocity&quot;">​</a></h3><ul><li><strong>Range</strong>: 0 - 127.</li><li>Controls the loudness (volume) of the sound.</li></ul><h3 id="_3-sustain" tabindex="-1">3. Sustain <a class="header-anchor" href="#_3-sustain" aria-label="Permalink to &quot;3. Sustain&quot;">​</a></h3><ul><li><strong>Unit</strong>: Tick (1/20th of a second).</li><li>Controls the duration before the sound wave ends.</li></ul><h3 id="_4-delay" tabindex="-1">4. Delay <a class="header-anchor" href="#_4-delay" aria-label="Permalink to &quot;4. Delay&quot;">​</a></h3><ul><li><strong>Unit</strong>: Milliseconds (ms).</li><li>This is a <strong>real-time delay</strong> setting. When the block is activated by a Redstone signal, it waits for the specified number of milliseconds before making a sound.</li><li>This allows for finer musical alignment than Redstone Repeaters (which have a 0.1s granularity).</li></ul><h3 id="_5-fade-in-out" tabindex="-1">5. Fade In/Out <a class="header-anchor" href="#_5-fade-in-out" aria-label="Permalink to &quot;5. Fade In/Out&quot;">​</a></h3><ul><li><strong>Unit</strong>: Tick.</li><li>Allows the sound to appear or disappear smoothly, avoiding abrupt cutoffs.</li></ul>',17)])])}const f=a(l,[["render",s]]);export{_ as __pageData,f as default};
